/*!
 * FacturaPorAquí — validación de formularios compatible (fv-compat 1.0).
 *
 * Implementación PROPIA del subconjunto de la API de FormValidation 1.x que usa
 * este proyecto. No contiene código de FormValidation (librería comercial que
 * nunca estuvo en el repositorio). Se conserva la ruta para no tocar las plantillas.
 *
 * API: FormValidation.formValidation(form, {fields, plugins, localization}),
 *      .on(evento, fn), .getPlugin(nombre), .revalidateField(campo),
 *      .disableValidator(campo[, validador]), .enableValidator(...), .resetForm([limpiar]),
 *      .validate(), .form
 * Eventos: core.validator.validated, core.element.validated, core.form.valid, core.form.invalid
 * Plugins: Trigger, SubmitButton, Bootstrap, Icon, Excluded (+ PasswordStrength en su archivo)
 * Validadores: notEmpty, stringLength, digits, numeric, regexp, callback, remote, date, file, identical
 */
(function (window, document) {
    'use strict';

    var utils = {
        classSet: function (element, classes) {
            if (!element) { return; }
            Object.keys(classes).forEach(function (names) {
                names.split(' ').filter(Boolean).forEach(function (name) {
                    element.classList.toggle(name, !!classes[names]);
                });
            });
        },
        closest: function (element, selector) {
            return element && element.closest ? element.closest(selector) : null;
        },
        format: function (message, params) {
            var values = Array.isArray(params) ? params : [params];
            var i = 0;
            return String(message).replace(/%s/g, function () { return values[i++] !== undefined ? values[i - 1] : ''; });
        }
    };

    function elementsOf(form, field) {
        var escaped = window.CSS && CSS.escape ? CSS.escape(field) : field.replace(/"/g, '\\"');
        return Array.prototype.slice.call(form.querySelectorAll('[name="' + escaped + '"]'));
    }

    function valueOf(elements) {
        var first = elements[0];
        if (!first) { return ''; }
        var type = (first.type || '').toLowerCase();
        if (type === 'radio' || type === 'checkbox') {
            return elements.filter(function (e) { return e.checked; }).map(function (e) { return e.value; }).join(',');
        }
        if (first.tagName === 'SELECT' && first.multiple) {
            return Array.prototype.slice.call(first.selectedOptions).map(function (o) { return o.value; }).join(',');
        }
        return first.value == null ? '' : String(first.value);
    }

    // ------------------------------------------------------------------ validadores
    // Cada validador recibe input = {value, element, elements, field, options, core}
    // y devuelve {valid, message?} o una promesa de ello. Vacío = válido salvo notEmpty.
    var validators = {
        notEmpty: function (input) {
            var el = input.element;
            if (el && el.type === 'file') { return {valid: el.files && el.files.length > 0}; }
            return {valid: input.value.trim() !== ''};
        },
        stringLength: function (input) {
            if (input.value === '') { return {valid: true}; }
            var o = input.options, length = input.value.length, min = o.min != null ? +o.min : null,
                max = o.max != null ? +o.max : null, msgs = input.core.localeOf('stringLength');
            var valid = (min === null || length >= min) && (max === null || length <= max);
            var message = min !== null && max !== null ? utils.format(msgs.between, [min, max])
                : min !== null ? utils.format(msgs.more, min) : utils.format(msgs.less, max);
            return {valid: valid, message: o.message || message};
        },
        digits: function (input) {
            return {valid: input.value === '' || /^\d+$/.test(input.value)};
        },
        numeric: function (input) {
            if (input.value === '') { return {valid: true}; }
            var o = input.options, value = input.value;
            if (o.thousandsSeparator) { value = value.split(o.thousandsSeparator).join(''); }
            if (o.decimalSeparator && o.decimalSeparator !== '.') { value = value.replace(o.decimalSeparator, '.'); }
            return {valid: /^[-+]?(\d+(\.\d*)?|\.\d+)$/.test(value) && isFinite(parseFloat(value))};
        },
        regexp: function (input) {
            if (input.value === '') { return {valid: true}; }
            var re = input.options.regexp instanceof RegExp ? input.options.regexp : new RegExp(input.options.regexp);
            return {valid: re.test(input.value)};
        },
        callback: function (input) {
            var result = input.options.callback ? input.options.callback(input) : true;
            return Promise.resolve(result).then(function (r) {
                return typeof r === 'object' && r !== null ? {valid: !!r.valid, message: r.message} : {valid: !!r};
            });
        },
        remote: function (input) {
            if (input.value === '') { return {valid: true}; }
            var o = input.options, method = (o.method || 'GET').toUpperCase();
            var data = typeof o.data === 'function' ? o.data(input) : (o.data || {});
            var params = new URLSearchParams();
            params.append(o.name || input.field, input.value);
            Object.keys(data).forEach(function (k) { params.set(k, data[k]); });
            var url = typeof o.url === 'function' ? o.url(input) : o.url;
            var init = {method: method, headers: Object.assign({'X-Requested-With': 'XMLHttpRequest'}, o.headers || {}),
                        credentials: 'same-origin'};
            if (method === 'GET') {
                url += (url.indexOf('?') === -1 ? '?' : '&') + params.toString();
            } else {
                init.body = params;
            }
            return fetch(url, init).then(function (r) { return r.json(); }).then(function (json) {
                return {valid: json.valid === true || json.valid === 'true', message: json.message};
            }).catch(function () {
                return {valid: false, message: input.core.localeOf('remote').default};
            });
        },
        date: function (input) {
            if (input.value === '') { return {valid: true}; }
            var format = (input.options.format || 'YYYY-MM-DD').toUpperCase().split(' ')[0];
            var order = format.match(/YYYY|MM|DD/g) || [];
            var separator = format.replace(/YYYY|MM|DD/g, '').charAt(0) || '-';
            var parts = input.value.split(' ')[0].split(separator);
            if (parts.length !== order.length) { return {valid: false, message: utils.format(input.core.localeOf('date').default, format)}; }
            var map = {};
            order.forEach(function (token, i) { map[token] = parts[i]; });
            var y = +map.YYYY, m = +map.MM, d = +map.DD;
            var date = new Date(y, m - 1, d);
            var valid = /^\d{4}$/.test(map.YYYY) && /^\d{1,2}$/.test(map.MM) && /^\d{1,2}$/.test(map.DD)
                && date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d;
            return {valid: valid, message: utils.format(input.core.localeOf('date').default, format)};
        },
        file: function (input) {
            var el = input.element, o = input.options;
            if (!el || !el.files || el.files.length === 0) { return {valid: true}; }
            var extensions = o.extension ? o.extension.toLowerCase().split(',').map(function (s) { return s.trim(); }) : null;
            var types = o.type ? o.type.toLowerCase().split(',').map(function (s) { return s.trim(); }) : null;
            if (o.maxFiles && el.files.length > +o.maxFiles) { return {valid: false}; }
            for (var i = 0; i < el.files.length; i++) {
                var f = el.files[i], ext = f.name.split('.').pop().toLowerCase();
                if (extensions && extensions.indexOf(ext) === -1) { return {valid: false}; }
                if (types && f.type && types.indexOf(f.type.toLowerCase()) === -1) { return {valid: false}; }
                if (o.maxSize && f.size > +o.maxSize) { return {valid: false}; }
            }
            return {valid: true};
        },
        identical: function (input) {
            var compare = input.options.compare;
            var other = typeof compare === 'function' ? compare() : valueOf(elementsOf(input.core.form, compare));
            return {valid: input.value === '' || input.value === other};
        }
    };

    // ------------------------------------------------------------------ núcleo
    function Core(form, options) {
        this.form = form;
        this.fields = options.fields || {};
        this.localization = options.localization || (FormValidation.locales.es_ES || {});
        this.plugins = {};
        this.handlers = {};
        this.disabled = {};
        this.runs = {};
        var self = this;
        Object.keys(options.plugins || {}).forEach(function (name) {
            var plugin = options.plugins[name];
            self.plugins[name] = plugin;
            if (plugin && plugin.install) { plugin.install(self); }
        });
    }

    Core.prototype.on = function (event, handler) {
        (this.handlers[event] = this.handlers[event] || []).push(handler);
        return this;
    };
    Core.prototype.off = function (event, handler) {
        this.handlers[event] = (this.handlers[event] || []).filter(function (h) { return h !== handler; });
        return this;
    };
    Core.prototype.emit = function (event, data) {
        (this.handlers[event] || []).slice().forEach(function (h) { h(data); });
    };
    Core.prototype.getPlugin = function (name) { return this.plugins[name]; };
    Core.prototype.getElements = function (field) { return elementsOf(this.form, field); };
    Core.prototype.localeOf = function (validator) {
        var l = this.localization[validator] || {};
        return typeof l === 'string' ? {default: l} : l;
    };
    Core.prototype.isExcluded = function (element) {
        var plugin = Object.keys(this.plugins).map(function (k) { return this.plugins[k]; }, this)
            .filter(function (p) { return p && p.isExcluded; })[0];
        return plugin ? plugin.isExcluded(element) : false;
    };
    Core.prototype.isValidatorEnabled = function (field, validator) {
        var d = this.disabled[field];
        return !(d === true || (d && d[validator]));
    };

    Core.prototype.validateField = function (field) {
        var self = this, definition = this.fields[field], elements = this.getElements(field);
        if (!definition || elements.length === 0 || this.isExcluded(elements[0])) { return Promise.resolve('Ignored'); }
        var run = (this.runs[field] || 0) + 1;
        this.runs[field] = run;
        var names = Object.keys(definition.validators || {}).filter(function (v) {
            var opts = definition.validators[v];
            return self.isValidatorEnabled(field, v) && !(opts && opts.enabled === false);
        });
        var element = elements[0], value = valueOf(elements);
        var chain = Promise.resolve(true);
        names.forEach(function (name) {
            chain = chain.then(function (ok) {
                if (!ok || self.runs[field] !== run) { return ok; }
                var fn = validators[name] || (FormValidation.validators[name]);
                if (!fn) { return true; }
                var options = definition.validators[name] || {};
                return Promise.resolve(fn({value: value, element: element, elements: elements, field: field,
                                           options: options, core: self})).then(function (result) {
                    if (self.runs[field] !== run) { return false; }
                    result = result || {valid: true};
                    if (!result.valid) {
                        // Prioridad: mensaje del campo > el calculado/del servidor > el genérico en español.
                        result.message = options.message || result.message || self.localeOf(name).default || 'Valor no válido';
                    }
                    self.emit('core.validator.validated', {element: element, elements: elements, field: field,
                                                            validator: name, result: result});
                    return result.valid;
                });
            });
        });
        return chain.then(function (valid) {
            if (self.runs[field] !== run) { return 'Ignored'; }
            self.emit('core.element.validated', {element: element, elements: elements, field: field, valid: valid});
            return valid ? 'Valid' : 'Invalid';
        });
    };

    Core.prototype.revalidateField = function (field) { return this.validateField(field); };

    Core.prototype.validate = function () {
        var self = this;
        return Promise.all(Object.keys(this.fields).map(function (f) { return self.validateField(f); }))
            .then(function (statuses) {
                var valid = statuses.indexOf('Invalid') === -1;
                self.emit(valid ? 'core.form.valid' : 'core.form.invalid', {});
                return valid ? 'Valid' : 'Invalid';
            });
    };

    Core.prototype.disableValidator = function (field, validator) {
        if (validator) {
            this.disabled[field] = this.disabled[field] === true ? true : (this.disabled[field] || {});
            if (this.disabled[field] !== true) { this.disabled[field][validator] = true; }
        } else {
            this.disabled[field] = true;
        }
        this.emit('core.field.reset', {field: field});
        return this;
    };

    Core.prototype.enableValidator = function (field, validator) {
        if (!validator || this.disabled[field] === true) {
            delete this.disabled[field];
        } else if (this.disabled[field]) {
            delete this.disabled[field][validator];
        }
        return this;
    };

    Core.prototype.resetForm = function (clear) {
        var self = this;
        Object.keys(this.fields).forEach(function (field) {
            self.runs[field] = (self.runs[field] || 0) + 1;
            if (clear) {
                self.getElements(field).forEach(function (el) {
                    if (el.type === 'checkbox' || el.type === 'radio') { el.checked = false; } else { el.value = ''; }
                });
            }
            self.emit('core.field.reset', {field: field});
        });
        return this;
    };

    // ------------------------------------------------------------------ plugins
    function Trigger(options) { this.options = options || {}; }
    Trigger.prototype.install = function (core) {
        var handler = function (e) {
            var name = e.target && e.target.name;
            if (!name || !core.fields[name]) { return; }
            var isText = /^(INPUT|TEXTAREA)$/.test(e.target.tagName) && !/^(checkbox|radio|file)$/.test(e.target.type);
            if ((e.type === 'input' && isText) || (e.type === 'change' && !isText)) { core.validateField(name); }
        };
        core.form.addEventListener('input', handler);
        core.form.addEventListener('change', handler);
    };

    function SubmitButton(options) { this.options = options || {}; }
    SubmitButton.prototype.install = function (core) {
        core.form.setAttribute('novalidate', 'novalidate');
        core.form.addEventListener('submit', function (e) {
            e.preventDefault();
            core.validate();
        });
    };

    function messageContainer(core, element) {
        var row = utils.closest(element, '.form-group') || element.parentNode;
        var container = row.querySelector('.fv-plugins-message-container');
        if (!container) {
            container = document.createElement('div');
            container.className = 'fv-plugins-message-container invalid-feedback';
            row.appendChild(container);
        }
        return container;
    }

    function Bootstrap(options) { this.options = options || {}; }
    Bootstrap.prototype.install = function (core) {
        core.form.classList.add('fv-plugins-bootstrap');
        core.on('core.validator.validated', function (e) {
            var container = messageContainer(core, e.element);
            var item = container.querySelector('[data-validator="' + e.validator + '"]');
            if (!e.result.valid) {
                if (!item) {
                    item = document.createElement('div');
                    item.className = 'fv-help-block';
                    item.setAttribute('data-field', e.field);
                    item.setAttribute('data-validator', e.validator);
                    container.appendChild(item);
                }
                item.textContent = e.result.message;
                Array.prototype.forEach.call(container.children, function (child) {
                    child.style.display = child === item ? 'block' : 'none';
                });
                container.classList.add('fv-show');
            } else if (item) {
                item.style.display = 'none';
            }
        });
        core.on('core.element.validated', function (e) {
            var row = utils.closest(e.element, '.form-group');
            var select2 = e.element.classList.contains('select2-hidden-accessible') ? e.element.nextElementSibling : null;
            [e.element, select2].forEach(function (el) {
                utils.classSet(el, {'is-valid': e.valid, 'is-invalid': !e.valid});
            });
            utils.classSet(row, {'has-success': e.valid, 'has-danger': !e.valid});
            if (e.valid) { messageContainer(core, e.element).classList.remove('fv-show'); }
        });
        core.on('core.field.reset', function (e) {
            core.getElements(e.field).forEach(function (el) {
                var select2 = el.classList.contains('select2-hidden-accessible') ? el.nextElementSibling : null;
                [el, select2].forEach(function (x) { utils.classSet(x, {'is-valid': false, 'is-invalid': false}); });
                utils.classSet(utils.closest(el, '.form-group'), {'has-success': false, 'has-danger': false});
                var container = (utils.closest(el, '.form-group') || el.parentNode).querySelector('.fv-plugins-message-container');
                if (container) { container.classList.remove('fv-show'); container.innerHTML = ''; }
            });
        });
    };

    function Icon(options) { this.options = options || {}; this.icons = new Map(); }
    Icon.prototype.install = function (core) {
        var self = this;
        core.on('core.element.validated', function (e) {
            var icon = self.icons.get(e.element);
            if (!icon) {
                icon = document.createElement('i');
                icon.setAttribute('aria-hidden', 'true');
                self.icons.set(e.element, icon);
            }
            icon.className = 'fv-plugins-icon ' + (e.valid ? self.options.valid || '' : self.options.invalid || '');
        });
    };

    function Excluded(options) { this.options = options || {}; }
    Excluded.prototype.install = function () {};
    Excluded.prototype.isExcluded = function (element) {
        if (this.options.excluded) { return !!this.options.excluded(element); }
        if (element.disabled || element.type === 'hidden') { return true; }
        if (element.classList.contains('select2-hidden-accessible')) { return false; }
        return element.offsetParent === null && element.getClientRects().length === 0;
    };

    var FormValidation = window.FormValidation || {};
    FormValidation.utils = utils;
    FormValidation.validators = Object.assign(FormValidation.validators || {}, validators);
    FormValidation.locales = FormValidation.locales || {};
    FormValidation.plugins = Object.assign(FormValidation.plugins || {}, {
        Trigger: Trigger, SubmitButton: SubmitButton, Bootstrap: Bootstrap, Icon: Icon, Excluded: Excluded
    });
    FormValidation.formValidation = function (form, options) { return new Core(form, options || {}); };
    FormValidation.Core = Core;
    window.FormValidation = FormValidation;
})(window, document);
